// Stages the MediaPipe Face Landmarker assets into public/ so the attention
// scoring feature can load them same-origin.
//
// Self-hosted on purpose: the model must never be fetched from a third-party
// CDN at runtime. That is not about the video (no frames ever leave the
// browser — detection is fully client-side), it's about not leaking the fact
// that a given session is running attention analysis to an outside host.
//
// The artifacts are build outputs, not source, so they are gitignored and
// regenerated by `prebuild` on every deploy.
import { mkdir, copyFile, readdir, access, stat } from 'node:fs/promises'
import { writeFile } from 'node:fs/promises'
import path from 'node:path'

const ROOT = path.resolve(import.meta.dirname, '..')
const WASM_SRC = path.join(ROOT, 'node_modules', '@mediapipe', 'tasks-vision', 'wasm')
const OUT = path.join(ROOT, 'public', 'mediapipe')
const WASM_OUT = path.join(OUT, 'wasm')
const MODEL_OUT = path.join(OUT, 'face_landmarker.task')
const MODEL_URL =
  'https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task'

await mkdir(WASM_OUT, { recursive: true })

for (const file of await readdir(WASM_SRC)) {
  await copyFile(path.join(WASM_SRC, file), path.join(WASM_OUT, file))
}
console.log(`[mediapipe] staged wasm runtime -> ${path.relative(ROOT, WASM_OUT)}`)

// The model is ~3.6MB and immutable, so skip the download when it's already
// staged. Keeps repeat builds fast and works offline once warmed.
const cached = await access(MODEL_OUT)
  .then(() => stat(MODEL_OUT))
  .then((s) => s.size > 0)
  .catch(() => false)

if (cached) {
  console.log('[mediapipe] model already staged, skipping download')
} else {
  const res = await fetch(MODEL_URL)
  if (!res.ok) throw new Error(`[mediapipe] model download failed: ${res.status}`)
  await writeFile(MODEL_OUT, Buffer.from(await res.arrayBuffer()))
  console.log(`[mediapipe] downloaded model -> ${path.relative(ROOT, MODEL_OUT)}`)
}
